// The client's way to the API (api/graphql.ts). request() POSTs one typed
// document from src/gql/ (generated by `npm run codegen` from the API's
// SDL) as JSON, which the server's CSRF check requires, and resolves to
// its data or to a message a form can show: a GraphQL error's own (the
// API words its refusals for people), or a generic one for anything else
// (a network failure, an abort, a 500). Nothing here throws into React.
// Documents are sent as the strings codegen wrote, so no GraphQL library
// reaches the browser.

import type { TypedDocumentString } from '../gql/graphql';

const ENDPOINT = '/api/graphql';
const GENERIC_ERROR = 'Something went wrong. Try again in a minute.';

/** What a request comes to: its data, or a readable error and the API's code for it. */
export type Result<T> = { ok: true; data: T } | { ok: false; error: string; code?: string; status?: string };

/** A GraphQL error as the API sends it: the message, and `extensions.code` (and `status` for a decision taken already). */
interface ApiError {
  message: string;
  code?: string;
  status?: string;
}

/** One GraphQL answer: its data and its errors. */
interface Answer<T> {
  data: T | null;
  errors: ApiError[];
}

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null;
const text = (v: unknown) => (typeof v === 'string' ? v : undefined);

/** The operation's name, which the e2e fixtures route on and Yoga reads from the document anyway. */
const operationName = (query: string) => /\b(?:query|mutation|subscription)\s+(\w+)/.exec(query)?.[1];

function body<TVariables>(document: TypedDocumentString<unknown, TVariables>, variables: TVariables): string {
  const query = document.toString();
  return JSON.stringify({ query, operationName: operationName(query), variables });
}

/**
 * Reads an answer's JSON: whatever it holds that has the shape of `data`
 * and `errors`. The data is trusted to match its document, which codegen
 * checked against the schema the API serves.
 */
function readAnswer<T>(json: unknown): Answer<T> {
  if (!isRecord(json)) return { data: null, errors: [] };
  const errors: unknown[] = Array.isArray(json.errors) ? json.errors : [];
  return {
    data: isRecord(json.data) ? (json.data as T) : null,
    errors: errors.filter(isRecord).map((e) => {
      const extensions = isRecord(e.extensions) ? e.extensions : {};
      return {
        message: text(e.message) ?? GENERIC_ERROR,
        code: text(extensions.code),
        status: text(extensions.status),
      };
    }),
  };
}

/** An answer as a Result: the first error if there is one, the data if the request went through. */
function settle<T>(answer: Answer<T>, ok: boolean): Result<T> {
  const [error] = answer.errors;
  if (error) return { ok: false, error: error.message, code: error.code, status: error.status };
  if (!ok || answer.data === null) return { ok: false, error: GENERIC_ERROR };
  return { ok: true, data: answer.data };
}

/** Sends one query or mutation. */
export async function request<TResult, TVariables>(
  document: TypedDocumentString<TResult, TVariables>,
  variables: TVariables,
  signal?: AbortSignal,
): Promise<Result<TResult>> {
  try {
    const response = await fetch(ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: body(document, variables),
      ...(signal ? { signal } : {}),
    });
    const json: unknown = await response.json().catch(() => null);
    return settle(readAnswer<TResult>(json), response.ok);
  } catch {
    return { ok: false, error: GENERIC_ERROR };
  }
}
